/*!
 * Themeasy — Audio Player
 *
 * Drives the custom chrome of the .tms-audio-player widget on top of the
 * server-rendered <audio> element. The markup ships a working native player
 * plus playlist rows that link straight to the files; this script adds the
 * --enhanced class, which is what reveals the custom UI and clips the native
 * controls away — so with no JS the visitor still gets a real player, and the
 * editor preview (--static) is left untouched.
 *
 * Behaviour: play/pause, a requestAnimationFrame progress loop (timeupdate
 * alone is too coarse for a smooth bar), range seeking, +/-15s skip, prev /
 * next and click-to-play across the playlist, a playback-rate cycle button, a
 * mute toggle, autoplay-next on ended with optional playlist looping, and
 * duration labels filled in from loadedmetadata. When one player starts, it
 * announces itself on the document so every other Themeasy player pauses —
 * two tracks never talk over each other.
 *
 * One AbortController per instance owns every listener; reset() aborts it and
 * restores the server state, so re-initialising is always safe.
 *
 * Namespace:    window.Themeasy.audioPlayer
 * Pattern:      IIFE + onDomReady() + boot()
 *
 * @author Themeasy
 * @link https://themeasy.co
 * @since 1.0.0
 */

(function (window, document) {
  'use strict'

  // ------------------------------------------------------------------------
  // Namespace
  // ------------------------------------------------------------------------
  window.Themeasy = window.Themeasy || {}
  window.Themeasy.audioPlayer = window.Themeasy.audioPlayer || {}

  // ------------------------------------------------------------------------
  // Constants
  // ------------------------------------------------------------------------
  const SELECTOR_WIDGET = '.tms-audio-player'
  const SELECTOR_NATIVE = '.tms-audio-player__native'
  const SELECTOR_COVER_IMG = '.tms-audio-player__cover-img'
  const SELECTOR_TITLE = '.tms-audio-player__title'
  const SELECTOR_ARTIST = '.tms-audio-player__artist'
  const SELECTOR_SCRUBBER = '.tms-audio-player__scrubber'
  const SELECTOR_TIME_CURRENT = '.tms-audio-player__time--current'
  const SELECTOR_TIME_TOTAL = '.tms-audio-player__time--total'
  const SELECTOR_PLAY = '.tms-audio-player__button--play'
  const SELECTOR_PREV = '.tms-audio-player__button--prev'
  const SELECTOR_NEXT = '.tms-audio-player__button--next'
  const SELECTOR_REWIND = '.tms-audio-player__button--rewind'
  const SELECTOR_FORWARD = '.tms-audio-player__button--forward'
  const SELECTOR_SPEED = '.tms-audio-player__button--speed'
  const SELECTOR_SPEED_LABEL = '.tms-audio-player__speed-label'
  const SELECTOR_MUTE = '.tms-audio-player__button--mute'
  const SELECTOR_ITEM = '.tms-audio-player__item'
  const SELECTOR_ITEM_LINK = '.tms-audio-player__item-link'
  const SELECTOR_ITEM_DURATION = '.tms-audio-player__item-duration'

  const CLASS_STATIC = 'tms-audio-player--static'
  const CLASS_ENHANCED = 'tms-audio-player--enhanced'
  const CLASS_PLAYING = 'tms-audio-player--playing'
  const CLASS_MUTED = 'tms-audio-player--muted'
  const CLASS_ITEM_ACTIVE = 'tms-audio-player__item--active'

  const PROP_PROGRESS = '--tms-audio-player-progress'
  const PROP_BUFFERED = '--tms-audio-player-buffered'

  const INIT_FLAG = 'tmsAudioPlayerInit'
  const DATA_KEY = '_tmsAudioPlayer'

  const EVENT_PLAY = 'themeasy/audio-player/play'
  const SKIP_SECONDS = 15
  const SCRUBBER_MAX = 1000
  const RATES = [1, 1.25, 1.5, 2]

  // ------------------------------------------------------------------------
  // Utils
  // ------------------------------------------------------------------------
  function onDomReady(fn) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', fn, { once: true })
      return
    }
    fn()
  }

  function getBoolAttr(el, name, fallback) {
    const raw = el.getAttribute(name)
    if (raw === null) return fallback
    return raw === 'true' || raw === '1' || raw === 'yes'
  }

  /**
   * Format seconds as m:ss, widening to h:mm:ss past the hour mark.
   *
   * @param {number} seconds Elapsed or total seconds.
   * @return {string} Clock label.
   */
  function formatClock(seconds) {
    if (!Number.isFinite(seconds) || seconds < 0) seconds = 0

    const total = Math.floor(seconds)
    const hours = Math.floor(total / 3600)
    const minutes = Math.floor((total % 3600) / 60)
    const secs = total % 60
    const pad = function (n) {
      return n < 10 ? '0' + n : String(n)
    }

    if (hours > 0) {
      return hours + ':' + pad(minutes) + ':' + pad(secs)
    }

    return minutes + ':' + pad(secs)
  }

  /**
   * Render a label template that carries a single %s placeholder.
   *
   * @param {string} template Template string.
   * @param {string} value    Replacement value.
   * @return {string} Rendered label.
   */
  function renderLabel(template, value) {
    if (!template) return ''
    if (template.indexOf('%s') === -1) return template

    // Function form: a track title containing $&, $' or $` would otherwise be
    // re-expanded by the replacement grammar and corrupt the label.
    return template.replace('%s', function () {
      return value
    })
  }

  function formatRate(rate) {
    // Trim the trailing zero so 1.5 reads "1.5x", not "1.50x".
    const text = String(parseFloat(rate.toFixed(2)))
    return text + '×'
  }

  // ------------------------------------------------------------------------
  // Track model — the playlist rows ARE the data source; each row carries the
  // file, the display strings and the authored duration as data attributes.
  // ------------------------------------------------------------------------
  function readTracks(root) {
    const links = root.querySelectorAll(SELECTOR_ITEM_LINK)

    return Array.prototype.map.call(links, function (link) {
      return {
        link: link,
        item: link.closest(SELECTOR_ITEM),
        src: link.getAttribute('data-src') || '',
        title: link.getAttribute('data-title') || '',
        artist: link.getAttribute('data-artist') || '',
        cover: link.getAttribute('data-cover') || '',
        duration: link.getAttribute('data-duration') || '',
      }
    })
  }

  // ------------------------------------------------------------------------
  // Painting
  // ------------------------------------------------------------------------
  function paintProgress(inst) {
    const audio = inst.audio
    const duration = audio.duration

    if (!Number.isFinite(duration) || duration <= 0) {
      inst.root.style.setProperty(PROP_PROGRESS, '0%')
      return
    }

    const ratio = Math.min(Math.max(audio.currentTime / duration, 0), 1)

    inst.root.style.setProperty(PROP_PROGRESS, (ratio * 100).toFixed(3) + '%')

    if (inst.scrubber && !inst.seeking) {
      inst.scrubber.value = String(Math.round(ratio * SCRUBBER_MAX))
      inst.scrubber.setAttribute('aria-valuetext', formatClock(audio.currentTime))
    }

    if (inst.timeCurrent) {
      inst.timeCurrent.textContent = formatClock(audio.currentTime)
    }
  }

  function paintBuffered(inst) {
    const audio = inst.audio
    const duration = audio.duration

    if (!Number.isFinite(duration) || duration <= 0 || !audio.buffered || !audio.buffered.length) {
      inst.root.style.setProperty(PROP_BUFFERED, '0%')
      return
    }

    // The range that contains the playhead is the one worth showing.
    let end = 0

    for (let i = 0; i < audio.buffered.length; i += 1) {
      if (audio.buffered.start(i) <= audio.currentTime && audio.buffered.end(i) >= audio.currentTime) {
        end = audio.buffered.end(i)
        break
      }
      end = Math.max(end, audio.buffered.end(i))
    }

    const ratio = Math.min(Math.max(end / duration, 0), 1)
    inst.root.style.setProperty(PROP_BUFFERED, (ratio * 100).toFixed(3) + '%')
  }

  function paintDuration(inst) {
    const duration = inst.audio.duration

    if (!inst.timeTotal || !Number.isFinite(duration) || duration <= 0) return

    inst.timeTotal.textContent = formatClock(duration)

    // Backfill the active playlist row when the author left its duration
    // blank — the real file metadata always beats a hand-typed placeholder.
    const track = inst.tracks[inst.index]

    if (track && track.item) {
      const cell = track.item.querySelector(SELECTOR_ITEM_DURATION)
      if (cell && !track.duration) cell.textContent = formatClock(duration)
    }
  }

  function syncPlayButton(inst) {
    const button = inst.playButton
    if (!button) return

    const track = inst.tracks[inst.index]
    const title = track ? track.title : ''
    const template = inst.audio.paused ? inst.labelPlay : inst.labelPause
    const label = renderLabel(template, title)

    if (label) button.setAttribute('aria-label', label)
  }

  function syncMuteButton(inst) {
    const button = inst.muteButton
    if (!button) return

    const muted = inst.audio.muted || inst.audio.volume === 0
    const label = muted ? inst.labelUnmute : inst.labelMute

    inst.root.classList.toggle(CLASS_MUTED, muted)
    if (label) button.setAttribute('aria-label', label)
  }

  // ------------------------------------------------------------------------
  // rAF loop — only while playing, so an idle player costs nothing.
  // ------------------------------------------------------------------------
  function tick(inst) {
    if (inst.destroyed) return

    paintProgress(inst)
    inst.raf = window.requestAnimationFrame(function () {
      tick(inst)
    })
  }

  function startLoop(inst) {
    if (inst.raf) return
    inst.raf = window.requestAnimationFrame(function () {
      tick(inst)
    })
  }

  function stopLoop(inst) {
    if (!inst.raf) return
    window.cancelAnimationFrame(inst.raf)
    inst.raf = null
  }

  // ------------------------------------------------------------------------
  // Track selection
  // ------------------------------------------------------------------------
  function markActive(inst) {
    inst.tracks.forEach(function (track, i) {
      if (!track.item) return
      track.item.classList.toggle(CLASS_ITEM_ACTIVE, i === inst.index)
    })
  }

  /**
   * Point the engine at a track, optionally starting playback.
   *
   * @param {Object}  inst  Instance state.
   * @param {number}  index Track index.
   * @param {boolean} play  Whether to play once the source is swapped.
   */
  function selectTrack(inst, index, play) {
    const track = inst.tracks[index]
    if (!track || !track.src) return

    const changed = index !== inst.index

    inst.index = index

    if (changed || inst.audio.getAttribute('src') !== track.src) {
      inst.audio.setAttribute('src', track.src)
      inst.audio.load()
    }

    if (inst.titleEl) inst.titleEl.textContent = track.title
    if (inst.artistEl) inst.artistEl.textContent = track.artist

    if (inst.coverImg) {
      if (track.cover) {
        inst.coverImg.setAttribute('src', track.cover)
        inst.coverImg.removeAttribute('srcset')
        inst.coverImg.hidden = false
      } else {
        // No art for this track: fall through to the styled placeholder.
        inst.coverImg.hidden = true
      }
    }

    if (inst.timeTotal) inst.timeTotal.textContent = track.duration || formatClock(0)
    if (inst.timeCurrent) inst.timeCurrent.textContent = formatClock(0)

    inst.root.style.setProperty(PROP_PROGRESS, '0%')
    inst.root.style.setProperty(PROP_BUFFERED, '0%')

    if (inst.scrubber) {
      inst.scrubber.value = '0'
      inst.scrubber.setAttribute('aria-valuetext', formatClock(0))
    }

    markActive(inst)
    syncPlayButton(inst)

    if (play) {
      const promise = inst.audio.play()
      // Autoplay can be refused (no gesture yet) — a rejection is not a fault.
      if (promise && typeof promise.catch === 'function') promise.catch(function () {})
    }
  }

  function step(inst, delta) {
    if (!inst.tracks.length) return

    let next = inst.index + delta

    if (next >= inst.tracks.length) {
      if (!inst.opts.loopPlaylist) return
      next = 0
    }

    if (next < 0) {
      if (!inst.opts.loopPlaylist) return
      next = inst.tracks.length - 1
    }

    selectTrack(inst, next, !inst.audio.paused)
  }

  // ------------------------------------------------------------------------
  // Wiring
  // ------------------------------------------------------------------------
  function on(inst, target, type, handler) {
    if (!target) return
    target.addEventListener(type, handler, { signal: inst.controller.signal })
  }

  function bindTransport(inst) {
    on(inst, inst.playButton, 'click', function () {
      if (inst.audio.paused) {
        const promise = inst.audio.play()
        if (promise && typeof promise.catch === 'function') promise.catch(function () {})
        return
      }
      inst.audio.pause()
    })

    on(inst, inst.root.querySelector(SELECTOR_REWIND), 'click', function () {
      inst.audio.currentTime = Math.max(0, inst.audio.currentTime - SKIP_SECONDS)
      paintProgress(inst)
    })

    on(inst, inst.root.querySelector(SELECTOR_FORWARD), 'click', function () {
      const duration = Number.isFinite(inst.audio.duration) ? inst.audio.duration : Infinity
      inst.audio.currentTime = Math.min(duration, inst.audio.currentTime + SKIP_SECONDS)
      paintProgress(inst)
    })

    on(inst, inst.root.querySelector(SELECTOR_PREV), 'click', function () {
      // Standard player courtesy: restart the track before stepping back.
      if (inst.audio.currentTime > 3) {
        inst.audio.currentTime = 0
        paintProgress(inst)
        return
      }
      step(inst, -1)
    })

    on(inst, inst.root.querySelector(SELECTOR_NEXT), 'click', function () {
      step(inst, 1)
    })

    on(inst, inst.speedButton, 'click', function () {
      inst.rateIndex = (inst.rateIndex + 1) % RATES.length

      const rate = RATES[inst.rateIndex]
      const text = formatRate(rate)

      inst.audio.playbackRate = rate

      if (inst.speedLabel) inst.speedLabel.textContent = text
      if (inst.labelSpeed) inst.speedButton.setAttribute('aria-label', renderLabel(inst.labelSpeed, text))
    })

    on(inst, inst.muteButton, 'click', function () {
      inst.audio.muted = !inst.audio.muted
      syncMuteButton(inst)
    })
  }

  function bindScrubber(inst) {
    const scrubber = inst.scrubber
    if (!scrubber) return

    const seekTo = function () {
      const duration = inst.audio.duration
      if (!Number.isFinite(duration) || duration <= 0) return

      const ratio = Math.min(Math.max(parseFloat(scrubber.value) / SCRUBBER_MAX, 0), 1)
      inst.audio.currentTime = ratio * duration
    }

    // While dragging, the input owns the value — the rAF loop must not fight it.
    on(inst, scrubber, 'pointerdown', function () {
      inst.seeking = true
    })

    on(inst, scrubber, 'input', function () {
      const duration = inst.audio.duration

      if (Number.isFinite(duration) && duration > 0) {
        const ratio = Math.min(Math.max(parseFloat(scrubber.value) / SCRUBBER_MAX, 0), 1)
        const preview = ratio * duration

        inst.root.style.setProperty(PROP_PROGRESS, (ratio * 100).toFixed(3) + '%')
        if (inst.timeCurrent) inst.timeCurrent.textContent = formatClock(preview)
        scrubber.setAttribute('aria-valuetext', formatClock(preview))
      }
    })

    on(inst, scrubber, 'change', function () {
      seekTo()
      inst.seeking = false
    })

    // Keyboard seeking never fires pointerdown, so release the lock defensively.
    on(inst, scrubber, 'keyup', function () {
      inst.seeking = false
    })
  }

  function bindPlaylist(inst) {
    inst.tracks.forEach(function (track, index) {
      on(inst, track.link, 'click', function (event) {
        if (!track.src) return
        // The row is a real link to the file (the no-JS path); once enhanced,
        // it drives the player instead of navigating away.
        event.preventDefault()
        selectTrack(inst, index, true)
      })
    })
  }

  function bindMedia(inst) {
    on(inst, inst.audio, 'play', function () {
      inst.root.classList.add(CLASS_PLAYING)
      syncPlayButton(inst)
      startLoop(inst)

      // Announce so sibling players stand down.
      document.dispatchEvent(new window.CustomEvent(EVENT_PLAY, { detail: { root: inst.root } }))
    })

    on(inst, inst.audio, 'pause', function () {
      inst.root.classList.remove(CLASS_PLAYING)
      syncPlayButton(inst)
      stopLoop(inst)
      paintProgress(inst)
    })

    on(inst, inst.audio, 'loadedmetadata', function () {
      paintDuration(inst)
      paintProgress(inst)
      paintBuffered(inst)
    })

    on(inst, inst.audio, 'progress', function () {
      paintBuffered(inst)
    })

    on(inst, inst.audio, 'timeupdate', function () {
      // Coarse, but it keeps the labels honest when the tab is throttled and
      // requestAnimationFrame stops firing.
      if (!inst.raf) paintProgress(inst)
    })

    on(inst, inst.audio, 'volumechange', function () {
      syncMuteButton(inst)
    })

    on(inst, inst.audio, 'ended', function () {
      inst.root.classList.remove(CLASS_PLAYING)
      stopLoop(inst)

      if (!inst.opts.autoplayNext || inst.tracks.length < 2) {
        syncPlayButton(inst)
        return
      }

      const isLast = inst.index >= inst.tracks.length - 1

      if (isLast && !inst.opts.loopPlaylist) {
        syncPlayButton(inst)
        return
      }

      selectTrack(inst, isLast ? 0 : inst.index + 1, true)
    })

    // Single-player courtesy: pause when another Themeasy player starts.
    on(inst, document, EVENT_PLAY, function (event) {
      if (!event.detail || event.detail.root === inst.root) return
      if (!inst.audio.paused) inst.audio.pause()
    })
  }

  // ------------------------------------------------------------------------
  // Instance lifecycle
  // ------------------------------------------------------------------------
  function readOptions(root) {
    return {
      autoplayNext: getBoolAttr(root, 'data-autoplay-next', true),
      loopPlaylist: getBoolAttr(root, 'data-loop-playlist', false),
    }
  }

  /**
   * Build (or skip) the player engine for one widget root.
   *
   * @param {HTMLElement} root The .tms-audio-player element.
   */
  function buildInstance(root) {
    // Editor preview is static: the chrome is already revealed by --static.
    if (root.classList.contains(CLASS_STATIC)) return

    // Prevent duplicate initialization.
    if (root.dataset[INIT_FLAG] === '1') return

    const audio = root.querySelector(SELECTOR_NATIVE)
    if (!audio) return

    const tracks = readTracks(root)

    // The playlist only renders for two-or-more tracks with the option on, so a
    // single-track player has no rows to read. The native element and the head
    // ARE the track — without this the chrome would never be enhanced and the
    // most common podcast setup would fall back to bare native controls.
    if (!tracks.length) {
      const headTitle = root.querySelector(SELECTOR_TITLE)
      const headArtist = root.querySelector(SELECTOR_ARTIST)
      const headTotal = root.querySelector(SELECTOR_TIME_TOTAL)

      tracks.push({
        link: null,
        item: null,
        src: audio.getAttribute('src') || '',
        title: headTitle ? headTitle.textContent.trim() : '',
        artist: headArtist ? headArtist.textContent.trim() : '',
        cover: '',
        duration: headTotal ? headTotal.textContent.trim() : '',
      })
    }

    root.dataset[INIT_FLAG] = '1'

    const playButton = root.querySelector(SELECTOR_PLAY)
    const speedButton = root.querySelector(SELECTOR_SPEED)
    const muteButton = root.querySelector(SELECTOR_MUTE)

    const inst = {
      root: root,
      audio: audio,
      tracks: tracks,
      index: 0,
      rateIndex: 0,
      raf: null,
      seeking: false,
      destroyed: false,
      controller: new AbortController(),
      opts: readOptions(root),

      coverImg: root.querySelector(SELECTOR_COVER_IMG),
      titleEl: root.querySelector(SELECTOR_TITLE),
      artistEl: root.querySelector(SELECTOR_ARTIST),
      scrubber: root.querySelector(SELECTOR_SCRUBBER),
      timeCurrent: root.querySelector(SELECTOR_TIME_CURRENT),
      timeTotal: root.querySelector(SELECTOR_TIME_TOTAL),
      playButton: playButton,
      speedButton: speedButton,
      speedLabel: root.querySelector(SELECTOR_SPEED_LABEL),
      muteButton: muteButton,

      labelPlay: playButton ? playButton.getAttribute('data-label-play') : '',
      labelPause: playButton ? playButton.getAttribute('data-label-pause') : '',
      labelMute: muteButton ? muteButton.getAttribute('data-label-mute') : '',
      labelUnmute: muteButton ? muteButton.getAttribute('data-label-unmute') : '',
      // The speed button ships a rendered label ("Playback speed: 1x") and no
      // template, so derive one from the rate it was rendered with.
      labelSpeed: '',
    }

    if (speedButton) {
      const rendered = speedButton.getAttribute('aria-label') || ''
      const initial = formatRate(RATES[0])
      inst.labelSpeed = rendered.indexOf(initial) === -1 ? '' : rendered.replace(initial, '%s')
    }

    root[DATA_KEY] = inst

    // The custom chrome is display:none until this class vouches for the
    // engine — content is never hidden without JS standing by to drive it.
    root.classList.add(CLASS_ENHANCED)

    bindTransport(inst)
    bindScrubber(inst)
    bindPlaylist(inst)
    bindMedia(inst)

    markActive(inst)
    syncPlayButton(inst)
    syncMuteButton(inst)
    paintProgress(inst)
  }

  /**
   * Kill listeners/loops and hand the widget back to its server state.
   *
   * @param {HTMLElement} root The .tms-audio-player element.
   */
  function teardown(root) {
    const inst = root[DATA_KEY]

    if (inst) {
      inst.destroyed = true
      stopLoop(inst)
      inst.controller.abort()

      if (!inst.audio.paused) inst.audio.pause()

      delete root[DATA_KEY]
    }

    root.classList.remove(CLASS_ENHANCED, CLASS_PLAYING, CLASS_MUTED)
    root.style.removeProperty(PROP_PROGRESS)
    root.style.removeProperty(PROP_BUFFERED)
    delete root.dataset[INIT_FLAG]
  }

  // ------------------------------------------------------------------------
  // Public API
  // ------------------------------------------------------------------------

  /**
   * Collect the players inside a scope, INCLUDING the scope itself when it is
   * one. querySelectorAll only matches descendants, so without this a caller
   * that hands over the widget's own root — the natural reading of "root" —
   * gets a silent no-op.
   *
   * @param {ParentNode} [root] Root node to scan. Defaults to document.
   * @returns {Array<HTMLElement>} Player roots, the scope itself first.
   */
  function collectWidgets(root) {
    const scope = root && root.querySelectorAll ? root : document
    const widgets = Array.prototype.slice.call(scope.querySelectorAll(SELECTOR_WIDGET))

    // document and DocumentFragment carry no matches().
    if (typeof scope.matches === 'function' && scope.matches(SELECTOR_WIDGET)) {
      widgets.unshift(scope)
    }

    return widgets
  }

  /**
   * Reset prior state inside a root (idempotent re-init support).
   *
   * @param {ParentNode} [root] Root node to scan. Defaults to document.
   */
  window.Themeasy.audioPlayer.reset = function (root) {
    collectWidgets(root).forEach(teardown)
  }

  /**
   * Initialize every Audio Player inside the given root (or document).
   *
   * @param {ParentNode} [root] Root node to scan. Defaults to document.
   */
  window.Themeasy.audioPlayer.init = function (root) {
    collectWidgets(root).forEach(buildInstance)
  }

  // ------------------------------------------------------------------------
  // Central boot
  // ------------------------------------------------------------------------
  function boot() {
    if (document.querySelector(SELECTOR_WIDGET)) {
      window.Themeasy.audioPlayer.init()
    }
  }

  window.Themeasy.audioPlayer.boot = boot

  // Auto-initialize on DOM ready.
  onDomReady(boot)
})(window, document)
